  m = /Nama\s*[:;.]?\s*([A-Za-z][A-Za-z .,'`-]{2,70}?)(?=\s{2,}|\s+Fakultas|\s+N\s?I\s?M\b|\n)/.exec(t);
  if (m) h.nama = m[1].replace(/\s+/g, ' ').trim();

