  });
  h.ipk = h.sks ? Math.round(h.mutu / h.sks * 100) / 100 : 0;

  if (!h.nim) h.catatan.push('NIM pada DKN tidak terbaca.');
  if (!kode.length) h.catatan.push('Baris mata kuliah tidak terbaca.');
  else if (terbaca.length < kode.length) h.catatan.push((kode.length - terbaca.length) + ' dari ' + kode.length + ' baris mata kuliah nilainya tidak terbaca.');
  if (h.jumlahSks === null) h.catatan.push('JUMLAH SKS di akhir DKN tidak terbaca. Pastikan halaman terakhir ikut diunggah.');
  else if (kode.length && h.sks !== h.jumlahSks) h.catatan.push('Jumlah SKS baris yang terbaca (' + h.sks + ') tidak sama dengan JUMLAH SKS pada DKN (' + h.jumlahSks + ').');
  if (h.ip === null) h.catatan.push('INDEX PRESTASI di akhir DKN tidak terbaca.');
  else if (h.sks && Math.abs(h.mutu / h.sks - h.ip) > 0.0101) h.catatan.push('IPK hasil hitung (' + h.ipk.toFixed(2) + ') tidak sama dengan INDEX PRESTASI pada DKN (' + h.ip.toFixed(2) + ').');

  var cocok = !!h.nim && kode.length >= 10 && terbaca.length === kode.length && yakin.length === kode.length &&
    h.jumlahSks !== null && h.sks === h.jumlahSks && h.ip !== null && Math.abs(h.mutu / h.sks - h.ip) <= 0.0101;
